mod dup {
    use forth::*;

    #[test]
    #[ignore]
    fn copies_a_value_on_the_stack() {
        let mut f = Forth::new();
        assert!(f.eval("1 dup").is_ok());
        assert_eq!(f.stack(), [1, 1]);
    }

    #[test]
    #[ignore]
    fn copies_the_top_value_on_the_stack() {
        let mut f = Forth::new();
        assert!(f.eval("1 2 dup").is_ok());
        assert_eq!(f.stack(), [1, 2, 2]);
