    #[test]
    #[ignore]
    fn swaps_the_top_two_values_on_the_stack_if_they_are_the_only_ones() {
        let mut f = Forth::new();
        assert!(f.eval("1 2 swap").is_ok());
        assert_eq!(f.stack(), [2, 1]);
