mod over {
    use forth::*;

    #[test]
    #[ignore]
    fn copies_the_second_element_if_there_are_only_two() {
        let mut f = Forth::new();
        assert!(f.eval("1 2 over").is_ok());
        assert_eq!(f.stack(), [1, 2, 1]);
    }

    #[test]
    #[ignore]
    fn copies_the_second_element_if_there_are_more_than_two() {
        let mut f = Forth::new();
        assert!(f.eval("1 2 3 over").is_ok());
