use std::rc::Rc;

pub type Value = i32;
pub type Result = std::result::Result<(), Error>;

#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    DivisionByZero,
    StackUnderflow,
    UnknownWord,
    InvalidWord,
}

/// A single executable instruction.
///
/// User-defined words are stored as a reference-counted list of `Op`s so
/// that redefining a word never copies the definitions it was built from;
/// only a pointer is shared.
#[derive(Clone)]
enum Op {
    Push(Value),
    Add,
    Sub,
    Mul,
    Div,
    Dup,
    Drop,
    Swap,
    Over,
    Word(Rc<Vec<Op>>),
}

pub struct Forth {
    stack: Vec<Value>,
    words: HashMap<String, Rc<Vec<Op>>>,
}

impl Forth {
    pub fn new() -> Forth {
        let mut words = HashMap::new();
        words.insert("+".to_string(), Rc::new(vec![Op::Add]));
        words.insert("-".to_string(), Rc::new(vec![Op::Sub]));
        words.insert("*".to_string(), Rc::new(vec![Op::Mul]));
        words.insert("/".to_string(), Rc::new(vec![Op::Div]));
        words.insert("dup".to_string(), Rc::new(vec![Op::Dup]));
        words.insert("drop".to_string(), Rc::new(vec![Op::Drop]));
        words.insert("swap".to_string(), Rc::new(vec![Op::Swap]));
        words.insert("over".to_string(), Rc::new(vec![Op::Over]));

        Forth {
            stack: Vec::new(),
            words,
        }
    }

    pub fn stack(&self) -> &[Value] {
        &self.stack
    }

    pub fn eval(&mut self, input: &str) -> Result {
        let tokens: Vec<&str> = input.split_whitespace().collect();
        let mut i = 0;
        while i < tokens.len() {
            if tokens[i] == ":" {
                let (consumed, ()) = self.define(&tokens[i + 1..])?;
                i += 1 + consumed;
            } else {
                let ops = self.resolve(tokens[i])?;
                self.run(&ops)?;
                i += 1;
            }
        }
        Ok(())
    }

    /// Parses and stores a definition starting right after the leading `:`.
    /// Returns the number of tokens consumed (including the trailing `;`).
    fn define(&mut self, tokens: &[&str]) -> std::result::Result<(usize, ()), Error> {
        let name = tokens.first().ok_or(Error::InvalidWord)?;
        if name.parse::<Value>().is_ok() {
            return Err(Error::InvalidWord);
        }
        let name = name.to_lowercase();

        let mut compiled = Vec::new();
        let mut idx = 1;
        loop {
            let token = tokens.get(idx).ok_or(Error::InvalidWord)?;
            idx += 1;
            if *token == ";" {
                break;
            }
            let ops = self.resolve(token)?;
            compiled.extend(ops.iter().cloned());
        }

        self.words.insert(name, Rc::new(compiled));
        Ok((idx, ()))
    }

    /// Resolves a single token into the ops it represents: either a numeric
    /// literal, a reference to the current definition of a word, or an
    /// error if the word is unknown.
    fn resolve(&self, token: &str) -> std::result::Result<Rc<Vec<Op>>, Error> {
        if let Ok(value) = token.parse::<Value>() {
            return Ok(Rc::new(vec![Op::Push(value)]));
        }
        let lower = token.to_lowercase();
        match self.words.get(&lower) {
            Some(def) => Ok(Rc::new(vec![Op::Word(Rc::clone(def))])),
            None => Err(Error::UnknownWord),
        }
    }

    fn run(&mut self, ops: &[Op]) -> Result {
        for op in ops {
            match op {
                Op::Push(v) => self.stack.push(*v),
                Op::Add => self.binary(|a, b| Ok(a + b))?,
                Op::Sub => self.binary(|a, b| Ok(a - b))?,
                Op::Mul => self.binary(|a, b| Ok(a * b))?,
                Op::Div => self.binary(|a, b| {
                    if b == 0 {
                        Err(Error::DivisionByZero)
                    } else {
                        Ok(a / b)
                    }
                })?,
                Op::Dup => {
                    let top = *self.stack.last().ok_or(Error::StackUnderflow)?;
                    self.stack.push(top);
                }
                Op::Drop => {
                    self.stack.pop().ok_or(Error::StackUnderflow)?;
                }
                Op::Swap => {
                    let len = self.stack.len();
                    if len < 2 {
                        return Err(Error::StackUnderflow);
                    }
                    self.stack.swap(len - 1, len - 2);
                }
                Op::Over => {
                    let len = self.stack.len();
                    if len < 2 {
                        return Err(Error::StackUnderflow);
                    }
                    let value = self.stack[len - 2];
                    self.stack.push(value);
                }
                Op::Word(def) => self.run(def)?,
            }
        }
        Ok(())
    }

    fn binary(
        &mut self,
        f: impl Fn(Value, Value) -> std::result::Result<Value, Error>,
    ) -> Result {
        let b = self.stack.pop().ok_or(Error::StackUnderflow)?;
        let a = self.stack.pop().ok_or(Error::StackUnderflow)?;
        self.stack.push(f(a, b)?);
        Ok(())
    }
}

impl Default for Forth {
    fn default() -> Forth {
        Forth::new()
    }
}
"}

